/* =========================================================================
 * 落第骑士英雄谭 · 破军伐刀者智能终端 v1.2.1 MONO ADV
 * 运行环境：TavernHelper 卡内脚本（script iframe）；UI 注入 ST 宿主 document
 * 结构：破军战术微光悬浮球(自由吸附) + 桌面浮动可拖拽终端(自由停靠与缩放) + 沙箱 iframe + MVU桥接
 * v1.2.1 更新：
 *   ① 决斗盘式水平展开动画（X轴压缩→弹性拉伸→稳定,扇形从左到右滑出）
 *   ② 终端打开时自动隐藏轮盘入口球
 *   ③ GBA 暖色调（深蓝紫#1A1832 + 暖金#F4D29C + 暖米白#F8F3E8 + 深红#C84A4A）*   ① 决斗盘式水平展开动画（X轴压缩→弹性拉伸→稳定,扇形从左到右滑出）
 *   ② 终端打开时自动隐藏轮盘入口球
 *   ③ 落第骑士配色（银白#E8E8E8 + 深红#8B0000 + 黑#0A0A0A）* ========================================================================= */
(async function () {
  'use strict';

  function hostWindow() {
    try { if (window.parent && window.parent !== window && window.parent.document) return window.parent; }
    catch (_) {}
    return window;
  }
  const HW = hostWindow();
  const HD = (function(){ try { return HW.document; } catch (_) { return document; } })();

  const SLOT = '__RK_PHONE_SHELL__';
  try { HW[SLOT] && HW[SLOT].destroy && HW[SLOT].destroy(); } catch (_) {}

  const SS = {
    mode: 'floating', visible: false,
    host: null, iframe: null, blobUrl: null, orb: null, style: null,
    rect: null, orbPos: {x: 0, y: 0},
    disposers: [], booted: false, mounting: null, destroyed: false, badge: 0,
    wheel: null, wheelBackdrop: null, wheelOpen: false, focusBeforeWheel: null
  };

  const LS = {
    get(k, d) { try { const v = HW.localStorage.getItem(k); return v == null ? d : JSON.parse(v); } catch(_) { return d; } },
    set(k, v) { try { HW.localStorage.setItem(k, JSON.stringify(v)); } catch(_) {} }
  };

  function fn(name) {
    try { if (typeof window[name] === 'function') return window[name]; } catch(_) {}
    try { if (window.TavernHelper && typeof window.TavernHelper[name] === 'function')
      return window.TavernHelper[name].bind(window.TavernHelper); } catch(_) {}
    return null;
  }

  const ORB_W = 68, ORB_H = 68;

  function viewport() {
    const vv = HW.visualViewport;
    let r = vv ? { x: vv.offsetLeft, y: vv.offsetTop, w: vv.width, h: vv.height }
               : { x: 0, y: 0, w: HW.innerWidth, h: HW.innerHeight };
    if (!isFinite(r.w) || !isFinite(r.h) || r.w < 50 || r.h < 50) {
      r = { x: 0, y: 0, w: HW.innerWidth, h: HW.innerHeight };
    }
    return r;
  }

  function preferDrawer() {
    try { return HW.innerWidth <= 768 || HW.matchMedia('(pointer: coarse)').matches; }
    catch(_) { return HW.innerWidth <= 768; }
  }

  function clampRect(r, vp) {
    const GAP = 10, MINW = 320, MINH = 500;
    const w = Math.min(Math.max(r.w, Math.min(MINW, vp.w - GAP * 2)), vp.w - GAP * 2);
    const h = Math.min(Math.max(r.h, Math.min(MINH, vp.h - GAP * 2)), vp.h - GAP * 2);
    return {
      x: Math.min(Math.max(r.x, vp.x + GAP), vp.x + vp.w - w - GAP),
      y: Math.min(Math.max(r.y, vp.y + GAP), vp.y + vp.h - h - GAP),
      w, h
    };
  }

  function clampOrb(x, y) {
    const vp = viewport();
    return {
      x: Math.min(Math.max(x, vp.x + 4), vp.x + vp.w - ORB_W - 4),
      y: Math.min(Math.max(y, vp.y + 4), vp.y + vp.h - ORB_H - 4)
    };
  }

  function fixedBase() {
    try {
      let el = HD.body;
      while (el) {
        const cs = HW.getComputedStyle(el);
        if (cs && (cs.transform !== 'none' || cs.perspective !== 'none' ||
                   (cs.filter && cs.filter !== 'none') ||
                   (cs.willChange && /transform|perspective/.test(cs.willChange)))) {
          const r = el.getBoundingClientRect();
          const sx = el.offsetWidth ? r.width / el.offsetWidth : 1;
          const sy = el.offsetHeight ? r.height / el.offsetHeight : 1;
          return { x: r.left, y: r.top, sx: sx || 1, sy: sy || 1 };
        }
        if (el === HD.documentElement) break;
        el = el.parentElement || HD.documentElement;
      }
    } catch(_) {}
    return { x: 0, y: 0, sx: 1, sy: 1 };
  }

  function writePos(el, vx, vy, vw, vh) {
    const b = fixedBase();
    el.style.left = ((vx - b.x) / b.sx) + 'px';
    el.style.top  = ((vy - b.y) / b.sy) + 'px';
    if (vw != null) el.style.width  = (vw / b.sx) + 'px';
    if (vh != null) el.style.height = (vh / b.sy) + 'px';
  }

  function placeOrb(p) {
    SS.orbPos = p;
    writePos(SS.orb, p.x, p.y);
  }

  function placeOrbTip() {
    const t = SS.orb && SS.orb.querySelector('.tip');
    if (!t || !t.classList.contains('on')) return;
    const vp = viewport();
    const isLeft = (SS.orbPos.x + ORB_W / 2) > (vp.x + vp.w / 2);
    t.classList.toggle('side-l', isLeft);
    t.classList.toggle('side-r', !isLeft);
  }

  function showOrbTip(title, body) {
    const t = SS.orb && SS.orb.querySelector('.tip');
    if (!t) return;
    t.replaceChildren();
    const heading = HD.createElement('b'); heading.textContent = title || '破军战术终端'; t.appendChild(heading);
    if (body) { const line = HD.createElement('s'); line.textContent = body; t.appendChild(line); }
    t.classList.add('on');
    placeOrbTip();
  }

  function clearOrbTip() {
    const t = SS.orb && SS.orb.querySelector('.tip');
    if (t) { t.classList.remove('on'); t.innerHTML = ''; }
  }

  function applyRect(r) {
    writePos(SS.host, r.x, r.y, r.w, r.h);
    SS.rect = r;
  }

  function defaultRect() {
    const vp = viewport();
    const w = Math.min(412, vp.w - 24);
    const h = Math.min(780, vp.h - 24);
    return {
      x: vp.x + Math.round((vp.w - w) / 2),
      y: vp.y + Math.round((vp.h - h) / 2),
      w, h
    };
  }

  function setMode(m) {
    SS.mode = m;
    if (m === 'drawer') {
      SS.host.classList.add('drawer');
      const vp = viewport();
      const w = Math.min(410, vp.w - 16);
      const h = Math.min(vp.h - 24, Math.max(500, Math.round(w * 1.9)));
      writePos(SS.host, vp.x + (vp.w - w) / 2, vp.y + (vp.h - h) / 2, w, h);
    } else {
      SS.host.classList.remove('drawer');
      applyRect(clampRect(LS.get('rk:rect', null) || defaultRect(), viewport()));
    }
  }

  function recenter() {
    const vp = viewport();
    placeOrb(clampOrb(vp.x + vp.w - ORB_W - 16, vp.y + Math.round(vp.h * 0.45)));
    LS.set('rk:orb', { x: SS.orbPos.x, y: SS.orbPos.y });
    const r = defaultRect();
    LS.set('rk:rect', r);
    if (SS.visible && SS.mode === 'floating') applyRect(clampRect(r, vp));
    return true;
  }

  /* 样式注入 */
  const css = `
#rk-orb,#rk-shell,#rk-wheel,#rk-wheel-curtain{box-sizing:border-box;font-family:"Microsoft YaHei UI","Noto Sans CJK SC",sans-serif;font-weight:400;font-size:14px;line-height:1.4;text-shadow:none;letter-spacing:normal}
#rk-shell *,#rk-wheel *{box-sizing:border-box}
#rk-orb{position:fixed;z-index:99990;width:${ORB_W}px;height:${ORB_H}px;padding:3px;background:#1A1832;color:#F4D29C;border:9px solid transparent;border-image:url("data:image/svg+xml;base64,") 16 stretch;display:flex;align-items:center;justify-content:center;cursor:pointer;user-select:none;touch-action:none;border-radius:0;box-shadow:3px 3px 0 #080808;outline:none}
#rk-orb .crest{display:flex;flex-direction:column;align-items:center;gap:1px;line-height:1.15;pointer-events:none}
#rk-orb .crest svg{display:block;width:27px;height:27px}
#rk-orb .crest span{font-family:"Noto Serif CJK SC","Songti SC","SimSun",serif;font-size:12px;letter-spacing:2px;white-space:nowrap}
#rk-orb:hover .crest,#rk-orb:focus-visible .crest{opacity:.72}
#rk-orb:focus-visible{outline:2px solid #fff;outline-offset:4px}
#rk-orb[aria-expanded="true"],#rk-shell.on ~ #rk-orb{visibility:hidden;pointer-events:none;}
#rk-orb .b{position:absolute;top:-12px;right:-12px;min-width:20px;height:20px;padding:0 3px;display:none;background:#8B0000;color:#F4D29C;border:2px solid #080808;font:bold 11px/16px Consolas,monospace;text-align:center;z-index:4;box-shadow:0 0 0 1px #fff}
#rk-orb .tip{position:absolute;top:50%;transform:translateY(-50%);width:180px;padding:8px 10px;background:#1A1832;border:3px double #F4D29C;box-shadow:0 0 0 2px #080808;color:#F4D29C;font:12px/1.5 "Microsoft YaHei UI",sans-serif;display:none;pointer-events:none;z-index:3;text-align:left}
#rk-orb .tip.on{display:block}#rk-orb .tip.side-l{right:calc(100% + 15px)}#rk-orb .tip.side-r{left:calc(100% + 15px)}
#rk-orb .tip b{display:block;font-size:12px;color:#F4D29C}#rk-orb .tip s{display:block;text-decoration:none;font-size:11px;color:#ccc;margin-top:3px}
#rk-shell{position:fixed;z-index:99991;background:#1A1832;color:#F4D29C;border:12px solid transparent;border-image:url("data:image/svg+xml;base64,") 16 stretch;border-radius:0;box-shadow:6px 6px 0 rgba(0,0,0,.65);display:none;flex-direction:column;overflow:hidden;isolation:isolate}
#rk-shell.on{display:flex}
#rk-shell .bar{height:36px;min-height:36px;display:flex;align-items:center;gap:8px;padding:0 5px 5px;cursor:grab;user-select:none;touch-action:none;background:#1A1832;border-bottom:3px double #fff}
#rk-shell.busy .bar{cursor:grabbing}#rk-shell.busy iframe{pointer-events:none}
#rk-shell .crest-label{font:600 13px "Noto Serif CJK SC","Songti SC","SimSun",serif;letter-spacing:2px;display:flex;align-items:center;gap:7px;white-space:nowrap;color:#F4D29C}
#rk-shell .crest-label svg{width:16px;height:16px;flex:none}
#rk-shell .bar-handle{flex:1;height:5px;max-width:35px;margin:auto;background:repeating-linear-gradient(90deg,#fff 0 2px,transparent 2px 5px);opacity:.5}
#rk-shell .bar button{display:flex;align-items:center;justify-content:center;flex:none;min-width:28px;width:28px;height:28px;margin:0;padding:0;border:1px solid #ddd;border-radius:0;background:#1A1832;color:#F4D29C;box-shadow:none;font:17px/1 Consolas,monospace;cursor:pointer}
#rk-shell .bar button:is(:hover,:focus-visible){background:#8B0000;color:#F4D29C;outline:1px solid #fff;outline-offset:2px}
#rk-shell iframe{display:block;flex:1;min-height:0;width:100%;border:0;background:#1A1832;color-scheme:dark}
#rk-shell .rsz{position:absolute;right:0;bottom:0;width:22px;height:22px;cursor:nwse-resize;touch-action:none;z-index:10;background:repeating-linear-gradient(135deg,transparent 0 3px,#fff 3px 4px,transparent 4px 6px);clip-path:polygon(100% 0,100% 100%,0 100%)}
#rk-shell.drawer .rsz{display:none}
#rk-wheel-curtain{position:fixed;display:none;z-index:99992;background:rgba(0,0,0,.16);touch-action:none}
#rk-wheel-curtain.on{display:block}
#rk-wheel{position:fixed;z-index:99993;display:none;user-select:none;touch-action:manipulation;color:#F4D29C;pointer-events:none;filter:drop-shadow(3px 4px 0 rgba(0,0,0,.6));background:transparent}
#rk-wheel.on{display:block;animation:rk-wheel-open 0.5s cubic-bezier(0.25,0.46,0.45,0.94);}.mono-sector{animation:rk-sector-slide 0.3s cubic-bezier(0.34,1.56,0.64,1) backwards;animation-delay:calc(var(--deploy-delay,0s) + 0.15s);}
#rk-wheel .mono-wheel-svg{pointer-events:none}#rk-wheel .mono-sector,#rk-wheel .mono-core,#rk-wheel .mono-wheel-close{pointer-events:auto}
#rk-wheel .mono-core{width:26%;height:26%;font-size:14px}
#rk-wheel .mono-wheel-caption{color:#F4D29C;background:#1A1832;border:3px double #F4D29C;padding:7px 3px;top:80%;left:26%;width:48%;height:auto}
#rk-wheel .mono-wheel-caption b{font-size:12px;letter-spacing:0}
#rk-wheel .mono-wheel-close{position:absolute;top:103%;left:50%;transform:translateX(-50%);padding:4px 16px;min-height:30px;border:2px solid #F4D29C;border-radius:0;background:#1A1832;color:#F4D29C;font:12px/1.2 "Microsoft YaHei UI",sans-serif;cursor:pointer;white-space:nowrap}
#rk-wheel .mono-wheel-close:is(:hover,:focus-visible){background:#8B0000;color:#F4D29C;outline:1px solid #080808}
@keyframes rk-wheel-open{
  0%{opacity:0;transform:scaleX(0.2) scaleY(0.6);}
  50%{transform:scaleX(1.08) scaleY(0.95);}
  100%{opacity:1;transform:scaleX(1) scaleY(1);}
}
@keyframes rk-sector-slide{
  from{transform:scaleX(0);transform-origin:50% 50%;}
  to{transform:scaleX(1);transform-origin:50% 50%;}
}
@media(prefers-reduced-motion:reduce){
  #rk-wheel.on{animation:rk-wheel-open-simple 0.2s ease-out;}
  @keyframes rk-wheel-open-simple{from{opacity:0;}to{opacity:1;}}
  .mono-sector{animation:none !important;}
}
@media(prefers-reduced-motion:reduce){#rk-wheel.on{animation:none}}

#rk-wheel .mono-wheel-svg{width:100%;height:auto;display:block;overflow:visible}
#rk-wheel .mono-sector{cursor:pointer;outline:none;--sector-ink:#F4D29C;--sector-bg:#1A1832}
#rk-wheel .mono-sector-shape{fill:var(--sector-bg);stroke:#F4D29C;stroke-width:2.8;vector-effect:non-scaling-stroke;stroke-linejoin:miter}
#rk-wheel .mono-sector-icon{fill:var(--sector-ink);pointer-events:none}
#rk-wheel .mono-sector-label{fill:var(--sector-ink);font:600 17px "Noto Serif CJK SC","Songti SC","SimSun",serif;text-anchor:middle;pointer-events:none;letter-spacing:1px}
#rk-wheel .mono-sector-no{fill:var(--sector-ink);opacity:.6;font:9px Consolas,monospace;text-anchor:middle;pointer-events:none}
#rk-wheel .mono-sector:is(:hover,:focus-visible){--sector-ink:#080808;--sector-bg:#fff}
#rk-wheel .mono-sector:is(:hover,:focus-visible) .mono-sector-shape{stroke:#080808;stroke-width:2.8}
#rk-wheel .mono-sector:active .mono-sector-shape{fill:#cfcfcf}
#rk-wheel .mono-core{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:94px;height:94px;padding:4px;display:flex;flex-direction:column;gap:2px;align-items:center;justify-content:center;z-index:2;background:#1A1832;color:#F4D29C;border:12px solid transparent;border-image:url("data:image/svg+xml;base64,") 16 stretch;font-family:"Noto Serif CJK SC","Songti SC","SimSun",serif;cursor:pointer;box-sizing:border-box;line-height:1.15}
#rk-wheel .mono-core span{font-size:15px;letter-spacing:2px;white-space:nowrap}
#rk-wheel .mono-aperture{width:34px;height:34px;flex:none;display:block}
#rk-wheel .mono-core:is(:hover,:focus-visible){filter:invert(1);outline:1px solid #fff;outline-offset:1px}
#rk-wheel .mono-wheel-caption{position:absolute;top:80%;left:30%;width:40%;text-align:center;line-height:1.65;color:#111;font-family:"Noto Serif CJK SC","Songti SC","SimSun",serif;pointer-events:none}
#rk-wheel .mono-wheel-caption b{display:block;font-size:13px;font-weight:700;letter-spacing:.5px}
#rk-wheel .mono-wheel-caption small{display:block;font:9px/1.6 Consolas,monospace;letter-spacing:1px}
#rk-wheel .mono-core{width:26%;height:26%}#rk-wheel .mono-wheel-caption{color:#F4D29C;background:#1A1832;top:80%;left:26%;width:48%;border:3px double #F4D29C;padding:7px 3px}
`;

  function buildDom() {
    SS.style = HD.createElement('style');
    SS.style.textContent = css;
    HD.head.appendChild(SS.style);

    SS.orb = HD.createElement('div');
    SS.orb.id = 'rk-orb';
    SS.orb.title = '点击展开操作轮盘；拖动可移动入口';
    SS.orb.setAttribute('role', 'button');
    SS.orb.setAttribute('tabindex', '0');
    SS.orb.setAttribute('aria-label', '打开终端操作轮盘');
    SS.orb.setAttribute('aria-expanded', 'false');
    SS.orb.setAttribute('aria-controls', 'rk-wheel');
    SS.orb.setAttribute('aria-haspopup', 'menu');
    SS.orb.innerHTML = "<div class=\"crest\"><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 32 32\" aria-hidden=\"true\" class=\"mono-aperture\" fill=\"currentColor\"><polygon points=\"16.63,1.47 28.58,8.37 21.71,16.16 19.95,11.31\"/><polygon points=\"28.90,9.28 28.90,23.08 18.72,21.03 22.03,17.07\"/><polygon points=\"28.27,23.81 16.32,30.71 13.00,20.87 18.09,21.76\"/><polygon points=\"15.37,30.53 3.42,23.63 10.29,15.84 12.05,20.69\"/><polygon points=\"3.10,22.72 3.10,8.92 13.28,10.97 9.97,14.93\"/><polygon points=\"3.73,8.19 15.68,1.29 19.00,11.13 13.91,10.24\"/></svg><span>操作</span></div><span class=\"b\"></span><span class=\"tip\" aria-hidden=\"true\"></span>";
    HD.body.appendChild(SS.orb);

    const op = LS.get('rk:orb', null), vp = viewport();
    const ox = op ? op.x : vp.x + vp.w - ORB_W - 16;
    const oy = op ? op.y : vp.y + Math.round(vp.h * 0.45);
    placeOrb(clampOrb(ox, oy));

    SS.host = HD.createElement('section');
    SS.host.id = 'rk-shell';
    SS.host.setAttribute('role', 'region');
    SS.host.setAttribute('aria-label', '破军战术终端');
    SS.host.innerHTML = `
